                "그다음부터는 지나가는 곳 이름이 줄줄이 나와요. 연추문, 경회 남문, 평구역, 흑수, 섬강, 치악, 소양강, 동주, 북관정이지요. 길을 따라가며 적는 이런 짜임을 여정이라고 해요. 여행기를 노래로 만든 셈이에요.",
