                "첫 도막에서 매달려요. 서경이 좋고 새로 닦은 이곳도 사랑하지만, 임과 헤어지느니 길쌈하던 베도 버리고 울며 따라가겠다고요. 살림살이를 버리겠다는 것은 삶의 터를 통째로 버리겠다는 말이에요.",
